		description:
			"Activity feed timeline with user avatars. Best for each event led by the actor's photo as its node, in one sentence that mutes the action between name and target.",
		file: "timeline-11",
		source:
			'import * as React from "react";\nimport { Timeline, TimelineContent, TimelineDate, TimelineHeader, TimelineIndicator, TimelineItem, TimelineSeparator } from "@workspace/ui/components/timeline";\n\nimport { Avatar, AvatarFallback, AvatarImage } from "@workspace/ui/components/avatar";\n\nconst activities = [\n\t{\n\t\tid: 1,\n\t\tuser: "Alex Johnson",\n\t\tavatar: "https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=96&h=96&dpr=2&q=80",\n\t\taction: "pushed 3 commits to",\n\t\ttarget: "main",\n\t\tdate: "5 minutes ago",\n\t},\n\t{\n\t\tid: 2,\n\t\tuser: "Sarah Chen",\n\t\tavatar: "https://images.unsplash.com/photo-1519699047748-de8e457a634e?w=96&h=96&dpr=2&q=80",\n\t\taction: "opened pull request",\n\t\ttarget: "#284 — Add dark mode",\n\t\tdate: "20 minutes ago",\n\t},\n\t{\n\t\tid: 3,\n\t\tuser: "David Kim",\n\t\tavatar: "https://images.unsplash.com/photo-1607990281513-2c110a25bd8c?w=96&h=96&dpr=2&q=80",\n\t\taction: "commented on",\n\t\ttarget: "Issue #142",\n\t\tdate: "1 hour ago",\n\t},\n\t{\n\t\tid: 4,\n\t\tuser: "Emma Wilson",\n\t\tavatar: "https://images.unsplash.com/photo-1485893086445-ed75865251e0?w=96&h=96&dpr=2&q=80",\n\t\taction: "deployed to",\n\t\ttarget: "production",\n\t\tdate: "2 hours ago",\n\t},\n\t{\n\t\tid: 5,\n\t\tuser: "Michael Rodriguez",\n\t\tavatar: "https://images.unsplash.com/photo-1584308972272-9e4e7685e80f?w=96&h=96&dpr=2&q=80",\n\t\taction: "merged branch",\n\t\ttarget: "feat/notifications",\n\t\tdate: "3 hours ago",\n\t},\n];\n\nexport function Timeline11Example(): React.JSX.Element {\n\treturn (\n\t\t<div className="w-full max-w-md">\n\t\t\t<Timeline defaultValue={5}>\n\t\t\t\t{activities.map((activity) => (\n\t\t\t\t\t<TimelineItem key={activity.id} step={activity.id} className="group-data-[orientation=vertical]/timeline:ms-10">\n\t\t\t\t\t\t<TimelineHeader>\n\t\t\t\t\t\t\t<TimelineSeparator className="bg-input! group-data-[orientation=vertical]/timeline:top-2 group-data-[orientation=vertical]/timeline:-left-8 group-data-[orientation=vertical]/timeline:h-[calc(100%-2.5rem)] group-data-[orientation=vertical]/timeline:translate-y-7" />\n\t\t\t\t\t\t\t<TimelineIndicator className="size-8 overflow-hidden rounded-full border-none group-data-[orientation=vertical]/timeline:-left-8">\n\t\t\t\t\t\t\t\t<Avatar className="size-8">\n\t\t\t\t\t\t\t\t\t<AvatarImage src={activity.avatar} alt={activity.user} />\n\t\t\t\t\t\t\t\t\t<AvatarFallback className="text-[10px]">\n\t\t\t\t\t\t\t\t\t\t{activity.user\n\t\t\t\t\t\t\t\t\t\t\t.split(" ")\n\t\t\t\t\t\t\t\t\t\t\t.map((name: string): string => name.charAt(0))\n\t\t\t\t\t\t\t\t\t\t\t.join("")}\n\t\t\t\t\t\t\t\t\t</AvatarFallback>\n\t\t\t\t\t\t\t\t</Avatar>\n\t\t\t\t\t\t\t</TimelineIndicator>\n\t\t\t\t\t\t</TimelineHeader>\n\t\t\t\t\t\t<TimelineContent>\n\t\t\t\t\t\t\t<p className="text-sm">\n\t\t\t\t\t\t\t\t<span className="font-medium">{activity.user}</span> <span className="text-muted-foreground">{activity.action}</span>{" "}\n\t\t\t\t\t\t\t\t<span className="font-medium">{activity.target}</span>\n\t\t\t\t\t\t\t</p>\n\t\t\t\t\t\t\t<TimelineDate className="mt-0.5 mb-0">{activity.date}</TimelineDate>\n\t\t\t\t\t\t</TimelineContent>\n\t\t\t\t\t</TimelineItem>\n\t\t\t\t))}\n\t\t\t</Timeline>\n\t\t</div>\n\t);\n}\n',
